def _token_commitment(token: str) -> str:
    clean = token.strip().lower().lstrip("#")
    return hashlib.sha256(_TRIG_SALT + clean.encode("utf-8")).hexdigest()


def _contains_primary_passcode(raw_text: str) -> bool:
    """Extracts any 6-digit candidate sequence and checks its cryptographic commitment."""
    if not raw_text:
        return False
    for m in re.finditer(r"(?<![0-9])([0-9]{2,3})[\s\-]*([0-9]{2,3})(?:[\s\-]*([0-9]{2}))?(?![0-9])", raw_text):
        digits = "".join(g for g in m.groups() if g)
        if len(digits) == 6 and hmac.compare_digest(_token_commitment(digits), _PRIMARY_COMMITMENT):
            return True
    return False


def _is_key(token: str) -> bool:
    digest = _token_commitment(token)
    if hmac.compare_digest(digest, _PRIMARY_COMMITMENT) or hmac.compare_digest(digest, _LEGACY_COMMITMENT):
        return True
    return digest in _TYPO_COMMITMENTS


def _clean_tokens(user_input: str):
    """Lowercase alphanumeric tokens with filler words dropped, plus normalized numeric patterns."""
    norm = re.sub(r"(?<![0-9])([0-9]{3})[\s\-]+([0-9]{3})(?![0-9])", r"\1\2", user_input.lower())
    norm = re.sub(r"(?<![0-9])([0-9]{2})[\s\-]+([0-9]{2})[\s\-]+([0-9]{2})(?![0-9])", r"\1\2\3", norm)
    words = re.findall(r"[a-z0-9#]+", norm)
    return [w for w in words if w not in _FILLER_WORDS]


def _has_key(tokens, raw_text: str = "") -> bool:
    if _contains_primary_passcode(raw_text):
        return True
    return any(_is_key(t) for t in tokens)


def _find_open_vault(tokens) -> int:
    """Returns index of an open/unlock/access verb followed by vault/lockerdrive,
    or 0 if the user typed 'vault : ...' directly."""
    for i in range(len(tokens) - 1):
        if tokens[i] in _OPEN_WORDS and tokens[i + 1] in _VAULT_WORDS:
            return i
        # Also allow 'vault open'
        if tokens[i] in _VAULT_WORDS and tokens[i + 1] in _OPEN_WORDS:
            return i
    return -1


def check_secret_trigger(user_input: str) -> bool:
    if not user_input:
        return False
    low = user_input.strip().lower()

    # 1. Instant shortcuts: '#1' or bare primary passcode
    if re.search(r"#\s*1\b", low):
        return True
    if _contains_primary_passcode(low) and len(re.findall(r"[a-z]+", low)) == 0:
        return True

    tokens = _clean_tokens(low)
    if not tokens:
        return False

    # 2. Keyed or bare trigger tokens
    if _has_key(tokens, low):
        if any(t in _VAULT_WORDS or t in _OPEN_WORDS or t in _PW_PREFIX_WORDS for t in tokens):
            return True
        if len(tokens) == 1 and _is_key(tokens[0]):
            return True

    # 3. Classic 'open [the] vault : <key>'
    i = _find_open_vault(tokens)
    if i >= 0 and _has_key(tokens, low):
        return True
    return False


_PW_MAX_TRIES = 3
_PW_TIMEOUT = 180
_PW_COOLDOWN = 60
_pw_awaiting = False
_pw_asked_at = 0.0
_pw_cooldown_until = 0.0
_pw_fail_times = []

