def _wrong_pw_msg(tries_left):
    if tries_left >= 2:
        return random.choice([
            f"nope!! wrong password 😂 vault stays closed ({tries_left} tries left)",
            f"hmm... NOPE. wrong one lol ({tries_left} tries left)",
        ])
    return random.choice([
        "nope!! wrong password 😂 vault stays closed (1 try left)",
        "NOT it lol. 1 try left, make it count!!",
    ])


def _record_wrong_pw(now: float):
    global _pw_awaiting, _pw_cooldown_until, _pw_fail_times
    _pw_fail_times = [t for t in _pw_fail_times if now - t < _PW_COOLDOWN]
    _pw_fail_times.append(now)
    if len(_pw_fail_times) < _PW_MAX_TRIES:
        return _wrong_pw_msg(_PW_MAX_TRIES - len(_pw_fail_times)), False
    _pw_awaiting = False
    _pw_cooldown_until = now + _PW_COOLDOWN
    return random.choice(_PASSWORD_FAIL_FINAL), False


def _password_flow(user_input: str):
    """2-step vault password flow. Returns (msg, triggered) or None."""
    global _pw_awaiting, _pw_asked_at, _pw_cooldown_until, _pw_fail_times
    now = time.time()
    low = user_input.strip().lower()

    # Step 2: Currently waiting for the user's password
    if _pw_awaiting:
        if now - _pw_asked_at > _PW_TIMEOUT:
            _pw_awaiting = False
        else:
            tokens = _clean_tokens(low)
            if _has_key(tokens, low):
                _pw_awaiting = False
                _request_timestamps.clear()
                return VAULT_TRIGGER_RESPONSE, True
            if not tokens:
                return random.choice(_PASSWORD_REASK), False
            if all(t in _CANCEL_WORDS for t in tokens):
                _pw_awaiting = False
                return random.choice(_PASSWORD_CANCEL_REPLIES), False
            # Strip prefix words like "password", "is", "pass", "it" so "password is 999999" counts as a try
            attempt_tokens = [
                t for t in tokens
                if t not in _PW_PREFIX_WORDS and t not in _OPEN_WORDS and t not in _VAULT_WORDS
            ]
            if len(attempt_tokens) >= 3:
                return random.choice(_PASSWORD_REASK), False
            return _record_wrong_pw(now)

    # Step 1: Check if user is asking to open/unlock the vault
    if now < _pw_cooldown_until:
        return None
