def _check_rate_limit():
    global _request_timestamps
    now = time.time()
    _request_timestamps = [t for t in _request_timestamps if now - t < WINDOW_SECONDS]
    if len(_request_timestamps) >= MAX_REQUESTS:
        return False, int(WINDOW_SECONDS - (now - _request_timestamps[0]))
    _request_timestamps.append(now)
    return True, 0


def _rate_limit_msg(wait):
    return f"⚠️ slow down!! rate limit is 5 msgs/min (im just regex lol, dont crash me). wait like {max(1, wait)}s and try again!"


def _remember_name(text):
    """returns a greeting if the user just told me their name, else None"""
    global _user_name
    m = re.search(
        r"\b(?:my\s+name(?:'s| is)\s+|i'?m\s+|call\s+me\s+|name'?s\s+)([a-z]{2,15})\b",
        text, re.IGNORECASE)
    if not m:
        return None
    candidate = m.group(1).lower()
    if candidate in _NOT_NAMES:
        return None  # "im bored" is not a name lol
    _user_name = candidate.capitalize()
    return random.choice([
        f"nice to meet u {_user_name}!! 🤝",
        f"{_user_name}, got it!! ill remember that 😎",
        f"yo {_user_name}!! welcome to kushal studios 🎮",
    ])


def _whats_my_name():
    if _user_name:
        return random.choice([
            f"ur {_user_name}!! i got a memory like a steel trap 😎",
            f"easy one - ur {_user_name} lol",
        ])
    return random.choice([
        "u havent told me yet!! say 'my name is ...' and ill remember 🧠",
        "no idea lol, u never said. try 'my name is ...'",
    ])


def get_response(user_input):
    # (special command goes first, dont tell anyone 😄)
    global _pw_awaiting
    if check_secret_trigger(user_input):
        _pw_awaiting = False
        _request_timestamps.clear()
        return VAULT_TRIGGER_RESPONSE, True

    # (v1.1: "open vault" without the key -> i ask for the password!! shhh)
    pw = _password_flow(user_input)
    if pw is not None:
        return pw

    text = user_input.strip().lower()

    # live clock! (i used to freeze time at app start, took me ages to fix lol)
    if re.search(r"\bwhat'?s\s+(the\s+)?time|time\s+(is\s+it|now)|current\s+time|\bclock\b", text):
        allowed, wait = _check_rate_limit()
        if not allowed:
            return _rate_limit_msg(wait), False
        return f"⏰ {time.strftime('%H:%M:%S')} on {time.strftime('%Y-%m-%d')} (ur pc clock, i dont have internet lol)", False
    if re.search(r"\bwhat'?s\s+(today|the\s+date)|today'?s\s+date|what\s+day\s+is\s+it|which\s+day", text):
        allowed, wait = _check_rate_limit()
        if not allowed:
            return _rate_limit_msg(wait), False
        return f"📅 today is {time.strftime('%A, %d %B %Y')} according to ur system clock!", False

    # name memory
    name_greet = _remember_name(text)
    if name_greet:
        allowed, wait = _check_rate_limit()
        if not allowed:
            return _rate_limit_msg(wait), False
        return name_greet, False
    if re.search(r"\bwhat'?s\s+my\s+name\b|\bknow\s+my\s+name\b|\bremember\s+me\b", text):
        allowed, wait = _check_rate_limit()
        if not allowed:
            return _rate_limit_msg(wait), False
        return _whats_my_name(), False

    allowed, wait = _check_rate_limit()
    if not allowed:
        return _rate_limit_msg(wait), False

    for pattern, responses in KNOWLEDGE_BASE:
        if re.search(pattern, text, re.IGNORECASE):
            return random.choice(responses), False

    return random.choice([
        "hmm idk that one 😅 try asking about the games, python, or just chat!",
        "sorry didnt catch that!! i know games, coding stuff, jokes n random facts. ask me those :D",
        "no clue lol, im just a regex bot. try 'list games' or 'python tips' or 'tell me a joke'!",
        "?? lol. i work best with stuff about kushal studios, games, python/js n tech things!",
        "thats outside my brain lol (its a small brain, its all regex). ask about games or coding!",
        "hmm my knowledge base says nothing about that 😂 try 'help' to see what i can do!!",
        "i dont think i can answer that, sry!! but i know alot about the 9 games, just ask :P",
        "wat? lol jk. ask me 'how to play snake' or 'tell me a fun fact' or something!!",
    ]), False


